#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.19.1  -  one clip at a time, comments over the clip, Activity
#   * A clip reply no longer plays under the one you were watching: only the clips
#     screen in front plays, and a clip in Discover goes quiet while one is open.
#   * With the comments open the clip shrinks into the space above the sheet, so it
#     stays visible while you read and type. Close the sheet and it grows back.
#   * NEW: the bell in the top right of Discover opens Activity - likes, comments,
#     replies and follows, newest first, with a red dot for what you have not read.
#     Activity is in-app only (no push notifications) and starts recording today.
# Run from the project root:   bash update_v1191_clip_focus.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="2536e2ad70a4d9d24fc4abb2adee357fb9f84985f6a31ab9cbc4b48707642a11"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: the free music update is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding the new packages to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p).read()
add = ""
if not re.search(r"^[ \t]+audio_merge:", s, re.M):
    add += "  audio_merge:\n    path: packages/audio_merge\n"
if not re.search(r"^[ \t]+file_picker:", s, re.M):
    add += "  file_picker: 10.3.10\n"
if add:
    m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
    if not m:
        sys.exit("ERROR: no dependencies: section in pubspec.yaml")
    s = s[:m.end()] + add + s[m.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added " + add.replace("\n", " ").strip())
else:
    print("    pubspec.yaml: already up to date")
PYX

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.1 is in place."
echo ""
echo "Good to know:"
echo "  * Nothing to set up: no key, no Vercel setting."
echo "  * Activity needs the new Firestore rules: firebase/firestore.rules now has a"
echo "    notifications block. Deploy it (Firebase console > Firestore > Rules) or the"
echo "    bell stays empty."
echo "  * There are no push notifications: the list fills in while the app is open."
exit 0

